const app=document.querySelector('#app');const mode=document.querySelector('meta[name="amiga-preview"][content="true"]')?'demo':'live';let api,session=null,config=null,loginError='',loginEmail='',loginPreparing=false,busy=false,generation=0,range='7',listPage=1;
