function toast(message,error=false){const t=document.querySelector('#toast');t.textContent=message;t.className=error?'error':'';t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',6500);}
function release(){closeWorkspaceDialog();releaseUploader();releaseProgress();for(const u of objectURLs)URL.revokeObjectURL(u);objectURLs=[];}
function pageTitle(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">AMIGA / ${escape(roleLabel(session?.user))}</div><h1>${title}</h1><p class="subtle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function navigate(page='queue',request='',invoice='',fullAgent=false){if(page==='agent'&&!fullAgent){openAssistantBubble(request?{requestId:request,invoiceId:invoice}:undefined);return;}if(unsavedChanges){toast('Simpan perubahan data sebelum berpindah halaman.',true);return;}if(request)latestRequest=request;if(invoice)selectedInvoice=invoice;const portal=portalForUser(session?.user);history.pushState(null,'',`/${portal}#${page}${request?'/'+encodeURIComponent(request):''}${invoice?'/'+encodeURIComponent(invoice):''}`);route();window.scrollTo({top:0});}
async function run(fn,refresh=true){if(busy)return;busy=true;document.querySelector('.content')?.classList.add('busy');document.querySelector('main')?.setAttribute('aria-busy','true');try{await fn();if(refresh)await route();}catch(e){if(e.status===401){session=null;loginError='Sesi berakhir. Silakan masuk kembali.';history.replaceState(null,'','/login');renderLogin();}else toast(e.message,true);}finally{busy=false;document.querySelector('.content')?.classList.remove('busy');document.querySelector('main')?.removeAttribute('aria-busy');}}
function renderLogin(){
  destroyAssistantBubble();
  unsavedChanges=false;release();generation++;
  const local=mode==='live'&&config?.auth_method!=='google';
  app.innerHTML=loginHTML({brand,themeControl,escape,email:loginEmail,error:loginError,preview:mode==='demo',local,register:local&&registerMode,ownerSetup:ownerSetupActive&&registerMode,company:companyRegistration});
  bindTheme();
  const input=document.querySelector('#login-email'),form=document.querySelector('#login-form'),submit=document.querySelector('#login-submit');
  function updateIntent(){
    loginEmail=input.value;
    let adminRequested=false,reviewerRequested=false,uploaderRequested=false;try{({adminRequested,reviewerRequested,uploaderRequested}=parseEmailInput(loginEmail));}catch{}
    companyRegistration=local&&registerMode&&!ownerSetupActive&&!adminRequested&&!reviewerRequested&&!uploaderRequested;
    form.dataset.intent=adminRequested?'admin-request':reviewerRequested?'reviewer-request':uploaderRequested?'uploader':'company-client';
    for(const id of ['registration-company','registration-telegram']){const section=document.getElementById(id);if(section){section.hidden=!companyRegistration;for(const field of section.querySelectorAll('input'))field.disabled=!companyRegistration;}}
    const companyName=document.querySelector('#company-name');if(companyName)companyName.required=companyRegistration;
    const googleCompany=document.querySelector('#google-company');if(googleCompany){googleCompany.hidden=adminRequested||reviewerRequested||uploaderRequested;document.querySelector('#google-company-name').disabled=googleCompany.hidden;}
    const intent=document.querySelector('#login-intent');intent.hidden=!registerMode||!(adminRequested||reviewerRequested||uploaderRequested);intent.textContent=uploaderRequested?'Akun Uploader':reviewerRequested?'Akun Reviewer':'Permintaan Admin';
    if(local&&registerMode&&!ownerSetupActive)document.querySelector('#login-title').textContent=uploaderRequested?'Daftar Uploader':reviewerRequested?'Daftar Reviewer':adminRequested?'Daftar Admin':'Daftar Klien perusahaan';
    submit.textContent=local&&registerMode?(ownerSetupActive?'Buat password & aktifkan':'Daftar'):'Masuk';
  }
  input.addEventListener('input',updateIntent);updateIntent();
  const toggle=document.querySelector('#login-toggle');
  if(toggle)toggle.onclick=()=>{if(loginPreparing||busy)return;registerMode=!registerMode;companyRegistration=false;loginError='';renderLogin();document.querySelector(registerMode?'#login-name':'#login-email')?.focus();};
  document.querySelector('#login-password-help')?.addEventListener('click',()=>{loginEmail=input.value;renderPassword();});
  form.onsubmit=async event=>{
    event.preventDefault();if(loginPreparing||busy)return;
    loginEmail=input.value;loginPreparing=true;submit.disabled=true;
    try{
      parseEmailInput(loginEmail);
      if(mode==='demo')await loginPreview(loginEmail);
      else if(local){
        if(!config)config=await api.config();
        const payload={email_input:loginEmail,password:document.querySelector('#login-password').value};
        if(registerMode){
          if(payload.password!==document.querySelector('#login-password-confirm').value)throw Error('Konfirmasi password belum sama. Ketik ulang passwordmu.');
          payload.display_name=document.querySelector('#login-name').value;if(companyRegistration){payload.account_type='company_client';payload.company_name=document.querySelector('#company-name').value.trim();}
          const contact=document.querySelector('#registration-telegram');if(contact&&!contact.hidden)payload.telegram_contact=document.querySelector('#register-telegram').value.trim();
          if(ownerSetupToken)payload.setup_token=ownerSetupToken;
        }
        session=await (registerMode?api.register(payload):api.login(payload));
        ownerSetupToken='';ownerSetupActive=false;registerMode=false;companyRegistration=false;loginError='';history.replaceState(null,'',`/${session.portal}#queue`);await route();
      }else await prepareGoogle();
    }catch(error){loginError=error.message;renderLogin();document.querySelector('#login-email')?.focus();}
    finally{loginPreparing=false;if(submit.isConnected)submit.disabled=false;}
  };
}
function renderPassword(reset=false){
  destroyAssistantBubble();release();generation++;
  let email=loginEmail;try{email=parseEmailInput(email).email;}catch{}
  app.innerHTML=passwordPageHTML({brand,themeControl,escape,email,reset});bindTheme();
  bindPasswordPage({root:app,api,reset,onBack:()=>{registerMode=false;loginError='';renderLogin();},onMethod:value=>{loginEmail=value;renderPassword(!reset);},onSuccess:value=>{loginEmail=value;session=null;registerMode=false;loginError='';history.replaceState(null,'','/login');}});
}
async function loginPreview(email_input){await run(async()=>{session=await api.login({email_input});history.replaceState(null,'',`/${session.portal}#queue`);await route();},false);}
async function prepareGoogle(){
  if(!config?.auth_configured||!config.google_client_id)throw Error('Login belum tersedia. Silakan hubungi pengelola AMIGA.');
  const loginGeneration=generation;
  if(!googleLoading)googleLoading=new Promise((resolve,reject)=>{
    if(window.google?.accounts?.id){resolve();return;}
    const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client?hl=id';script.async=true;
    script.onload=resolve;script.onerror=()=>{googleLoading=null;reject(Error('Verifikasi akun belum dapat dimuat. Periksa koneksi dan coba lagi.'));};document.head.append(script);
  });
  await googleLoading;if(loginGeneration!==generation)return;
  window.google.accounts.id.initialize({client_id:config.google_client_id,auto_select:false,callback:response=>{
    if(loginGeneration!==generation)return;
    run(async()=>{
      parseEmailInput(loginEmail);
      const company=document.querySelector('#google-company-name');
      session=await api.login({credential:response.credential,email_input:loginEmail,...(company&&!company.disabled&&company.value.trim()?{company_name:company.value.trim()}:{})});
      history.replaceState(null,'',`/${session.portal}#queue`);await route();
    },false);
  }});
  const target=document.querySelector('#google-button');target.replaceChildren();
  window.google.accounts.id.renderButton(target,{type:'standard',theme:'outline',size:'large',text:'continue_with',width:300,locale:'id'});
  document.querySelector('#login-submit').hidden=true;
}
function navigation(){const u=session.user;if(session.portal==='client')return [{id:'queue',label:'Progres perusahaan'},{id:'voucher',label:'Voucher perusahaan'},{id:'telegram',label:'Telegram penerima'},{id:'help',label:'Panduan klien'}];if(session.portal==='pending')return [{id:'help',label:'Status akun'}];if(session.portal==='reviewer')return [{id:'queue',label:'Tugas tersedia'},{id:'my-tasks',label:'Tugas saya'},{id:'voucher',label:'Voucher reviewer'},{id:'help',label:'Cara kerja reviewer'}];if(session.portal==='admin')return [{id:'queue',label:'Ringkasan pekerjaan'},{id:'tasks',label:'Pantau penugasan'},...(canManageUsers(u)?[{id:'users',label:'Reviewer & akun'}]:[]),{id:'help',label:'Panduan admin'}];return [{id:'queue',label:'Ringkasan saya'},{id:'upload',label:'Unggah invoice'},{id:'requests',label:'Dokumen saya'},{id:'voucher',label:'Voucher saya'},{id:'help',label:'Cara kerja uploader'}];}
function shell(content,page='queue'){const u=session.user,nav=navigation(),label=nav.find(x=>x.id===page)?.label??'Detail dokumen';app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="workspace-label"><span class="workspace-dot"></span>Portal ${escape(roleLabel(u))}</div><div class="nav-label">Ruang kerja</div><nav class="nav">${nav.map(n=>`<a href="#${n.id}" data-nav="${n.id}" aria-label="${n.label}" class="${page===n.id?'active':''}">${icon(n.id)}<span>${n.label}</span></a>`).join('')}</nav><div class="side-bottom"><div class="sidebar-card"><div class="card-kicker">Review independen</div><strong>${session.portal==='client'?'Proses perusahaanmu, jelas.':session.portal==='uploader'?'Dokumenmu, tertelusur.':'Review yang independen.'}</strong><p>${session.portal==='client'?'Pantau penanggung jawab, progres dan voucher perusahaan.':session.portal==='uploader'?'Unggah, lengkapi bukti, dan pantau prosesnya.':'Periksa invoice sebelum voucher diterbitkan.'}</p></div><div class="side-note">AMIGA · Robot Admin</div></div></aside><div class="main"><header class="topbar"><div class="crumb">${escape(roleLabel(u))} <span>/</span><strong>${escape(label)}</strong></div><div class="topbar-tools"><span class="demo-pill"><i></i>${mode==='demo'?'Pratinjau • Identitas & ekstraksi simulasi':'Sesi aktif'}</span>${themeControl()}<div class="portal-user"><strong>${escape(u.display_name)}</strong><small>${escape(roleLabel(u))}</small></div><button id="logout" class="small">Keluar</button></div></header><main class="content${busy?' busy':''}" aria-busy="${busy}">${mode==='demo'&&api.warning?.()?`<div class="callout warn">${escape(api.warning())}</div>`:''}${content}<div class="footer-note"><span class="workspace-dot"></span>Voucher administrasi AMIGA bukan otorisasi pembayaran.</div></main></div></div>`;bindTheme();syncAssistantBubble({api,session,escape,navigate:(p,r,i)=>navigate(p,r,i,true),onUnauthorized:()=>{session=null;loginError='Sesi berakhir. Masuk kembali untuk melanjutkan.';history.replaceState(null,'','/login');renderLogin();},hidden:page==='agent'||session.portal==='client'});document.querySelectorAll('[data-nav]').forEach(a=>a.onclick=e=>{e.preventDefault();navigate(a.dataset.nav,['history','review'].includes(a.dataset.nav)?latestRequest:'');});document.querySelector('#logout').onclick=()=>{if(unsavedChanges){toast('Simpan atau batalkan perubahan sebelum keluar.',true);return;}run(async()=>{await api.logout();session=null;history.replaceState(null,'','/login');renderLogin();},false);};}
function pendingPage(){const u=session.user;shell(pageTitle('Aktivasi belum selesai','Akun telah dikenali, tetapi akses workspace belum diberikan.')+`<section class="panel"><div class="panel-body"><h2>${u.account_status==='PENDING_ADMIN'?'Permintaan aktivasi admin':u.account_status==='PENDING_REVIEWER'?'Permintaan aktivasi reviewer':u.account_status==='PENDING_COMPANY'?'Hubungkan perusahaan':'Status akun: '+escape(u.account_status)}</h2><p>${escape(u.email)}</p>${u.requested_company_name?`<p>Perusahaan: <strong>${escape(u.requested_company_name)}</strong></p><p>Admin akan menghubungkan akun ini ke perusahaan yang benar. Setelah aktif, masuk kembali dengan email biasa.</p>`:''}<div class="callout warn">${mode==='demo'?'Ini simulasi pendaftaran. Permintaan akses belum disetujui.':'Akun ini belum memiliki akses perusahaan atau peran aktif. Admin mengatur perusahaan dari Reviewer & akun. Untuk admin tambahan, pengelola yang sudah aktif perlu menetapkan peran admin. Jika ini akun pemilik pertama, gunakan tautan penyiapan dari launcher lokal.'}</div><p class="subtle">Setelah peran aktif, login berikutnya cukup memakai email biasa tanpa /admin atau /view.</p><button id="refresh-account" class="primary">Periksa status aktivasi</button></div></section>`,'help');document.querySelector('#refresh-account').onclick=()=>run(async()=>{session=await api.me();history.replaceState(null,'',`/${portalForUser(session.user)}#queue`);});}
function tableHTML(result,{vouchersOnly=false}={}){const rows=vouchersOnly?result.items.filter(r=>(r.voucher_count??(['AMIGA_REVIEWED','SENT_TO_CLIENT'].includes(requestStatus(r.status))?1:0))>0):result.items;return `<section class="panel queue-panel"><div class="panel-head"><h2>${vouchersOnly?'Voucher yang tersedia':'Invoice & permintaan'}</h2><span class="subtle">${result.total} request sesuai akses</span></div><div class="toolbar"><input id="search" placeholder="Cari request, vendor, atau nomor invoice…" aria-label="Cari dokumen" value="${escape(search)}"><select id="status-filter" aria-label="Filter status"><option value="">Semua status</option>${Object.entries(statusLabels).map(([k,v])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${v}</option>`).join('')}</select><select id="lifecycle-filter" aria-label="Filter buka tutup"><option value="">Terbuka & ditutup</option><option value="OPEN" ${lifecycleFilter==='OPEN'?'selected':''}>OPEN · Terbuka</option><option value="CLOSED" ${lifecycleFilter==='CLOSED'?'selected':''}>CLOSED · Ditutup</option></select><button id="search-go">Cari</button><button id="search-clear">Reset</button></div><p class="list-open-hint subtle">Klik dua kali pada baris untuk membuka, atau tekan Enter saat baris dipilih.</p><div class="table-scroll"><table><thead><tr><th>Request / klien</th><th>Vendor / invoice</th><th class="amount">Nominal</th><th>Status</th><th>Penanggung jawab</th><th>Pembaruan</th></tr></thead><tbody>${rows.map(r=>`<tr data-open-request="${escape(r.id)}" aria-label="Buka ${escape(requestLabel(r))}, klik dua kali atau Enter"><td><strong>${escape(requestLabel(r))}</strong><small>${escape(r.client_name)}</small><button class="small open-request" data-request="${escape(r.id)}">${requestOpenLabel(r,session.portal,vouchersOnly)}</button></td><td><strong>${escape(r.vendor_names.join(', '))}</strong><small>${escape(r.invoice_numbers.join(', '))}${r.invoice_count>1?' · '+r.invoice_count+' invoice':''}</small></td><td class="amount">${r.totals_by_currency.map(t=>escape(money(t.amount,t.currency))).join('<br>')||'Belum tersedia'}</td><td>${workBadge(r,escape)}${requestBadge(r,escape,badge)}<small>${r.issues.filter(i=>!i.resolved).length} indikasi aktif</small></td><td>${escape(r.pic_name||'Belum diambil')}</td><td>${stamp(r.updated_at)}</td></tr>`).join('')||'<tr><td class="empty" colspan="6">Belum ada dokumen yang sesuai.</td></tr>'}</tbody></table></div><div class="table-footer"><span>Halaman ${result.page} · ${result.items.length} request dimuat</span><div class="actions"><button id="prev-page" class="small" ${result.page<=1?'disabled':''}>Sebelumnya</button><button id="next-page" class="small" ${result.page*result.page_size>=result.total?'disabled':''}>Berikutnya</button></div></div></section>`;}
function bindTable(page){bindDoubleOpen(document,'[data-open-request]',row=>navigate(page==='voucher'?'voucher':'review',row.dataset.openRequest));document.querySelectorAll('.open-request').forEach(b=>b.onclick=()=>navigate(page==='voucher'?'voucher':'review',b.dataset.request));const doSearch=()=>{search=document.querySelector('#search').value;statusFilter=document.querySelector('#status-filter').value;lifecycleFilter=document.querySelector('#lifecycle-filter').value;listPage=1;route();};document.querySelector('#search-go').onclick=doSearch;document.querySelector('#search').onkeydown=e=>{if(e.key==='Enter')doSearch();};document.querySelector('#status-filter').onchange=doSearch;document.querySelector('#lifecycle-filter').onchange=doSearch;document.querySelector('#search-clear').onclick=()=>{search='';statusFilter='';lifecycleFilter='';listPage=1;route();};document.querySelector('#prev-page').onclick=()=>{listPage--;route();};document.querySelector('#next-page').onclick=()=>{listPage++;route();};}
async function dashboard(page,token){const result=await api.list({page:listPage,page_size:50,search,status:statusFilter,lifecycle:mode==='live'?lifecycleFilter:'',has_voucher:page==='voucher'&&mode==='live'?'1':''});if(token!==generation)return;
  const items=result.items;let charts='';if(page==='queue'){
    const domain=mode==='demo'?api.chartRequests():items.map(r=>({id:r.id,status:requestStatus(r.status),pic:r.pic_id??'Belum ditugaskan',audit:[],versions:[],reviews:[],vouchers:[]}));
    charts=analyticsHTML(domain,range,id=>DEMO_ACCOUNTS.find(u=>u.id===id)?.name??id);
  }
  shell(pageTitle(page==='voucher'?'Voucher siap diunduh':session.portal==='uploader'?'Ruang kerja uploader.<br><span class="heading-soft">Dokumenmu, tertelusur.</span>':'Seluruh pekerjaan.<br><span class="heading-soft">Satu pandangan.</span>',session.portal==='uploader'?'Kelola invoice dan bukti milik klien yang ditugaskan ke akunmu.':'Antrean, review, dan penyerahan voucher dalam satu workspace.',canUpload(session.user)?'<button id="upload-new" class="primary">＋ Unggah invoice</button>':'')+(page==='queue'?`<div class="stats">${[['Request dimuat',items.length],['Belum diambil',items.filter(r=>r.work_status==='UNCLAIMED').length],['Sedang dikerjakan',items.filter(r=>r.work_status==='IN_REVIEW').length],['Pekerjaan ditutup',items.filter(r=>r.lifecycle?.state==='CLOSED').length]].map(([label,n])=>`<div class="stat"><div class="stat-title">${label}</div><div class="stat-number" data-count="${n}">${n}</div><div class="stat-foot">${mode==='demo'?'Data pratinjau sesuai akses':'Ringkasan hasil pada halaman ini'}</div></div>`).join('')}</div>${charts}`:'')+tableHTML(result,{vouchersOnly:page==='voucher'}),page);document.querySelector('#upload-new')?.addEventListener('click',()=>navigate('upload'));bindTable(page);
  if(page==='queue'){
    if(mode==='live'){document.querySelector('.activity-panel').innerHTML='<div class="panel-head"><h2>Aktivitas pekerjaan</h2></div><div class="panel-body"><p class="subtle">Lihat riwayat pada setiap request untuk mengikuti perkembangan pekerjaan.</p></div>';document.querySelector('.progress-panel .tiny-tag').textContent='Halaman ini';}
    document.querySelector('#chart-range')?.addEventListener('change',e=>{range=e.target.value;route();});document.querySelectorAll('[data-chart-status]').forEach(b=>b.onclick=()=>{const map={done:'SENT_TO_CLIENT',handover:'AMIGA_REVIEWED',review:'READY_FOR_REVIEW',exception:'EXCEPTION',processing:'QUEUED,PROCESSING'};statusFilter=map[b.dataset.chartStatus];navigate('requests');});document.querySelectorAll('[data-team-pic]').forEach(b=>{b.disabled=true;b.title='Ringkasan penugasan reviewer.';});animateNumbers(JSON.stringify(items.map(r=>[r.id,r.status,r.updated_at]))+range);
  }
}
