function legacyUploadPage(){if(!canUpload(session.user))throw Error('Peran ini tidak memiliki izin unggah.');shell(pageTitle('Unggah invoice','Buat request untuk klien yang ditugaskan ke akunmu.')+`<div class="upload-layout"><section class="panel"><div class="panel-body"><form id="upload-form"><div class="form-grid"><div><label for="client-id">Klien</label><select id="client-id" name="client_id">${session.user.clients.map(c=>`<option value="${escape(c.id)}">${escape(c.name)}</option>`).join('')}</select></div><div><label for="request-type">Jenis permintaan</label><select id="request-type" name="request_type"><option>Invoice vendor</option></select></div><div><label for="source-channel">Saluran</label><select id="source-channel" name="channel"><option>Portal</option><option>Email</option><option>WhatsApp</option></select></div><div><label for="request-date">Tanggal</label><input id="request-date" name="request_date" type="date" value="${dateKey(new Date())}" required></div><div class="full"><label for="deadline">Tenggat pekerjaan</label><input id="deadline" name="deadline" type="date" required></div><div class="full"><label class="dropzone" for="invoice-file" id="dropzone"><strong>↑ Pilih atau tarik PDF / foto invoice</strong><small>PDF maksimal 5 halaman; PDF atau foto maksimal 10 MB. Foto disiapkan menjadi PDF oleh sistem.</small><input id="invoice-file" name="invoice_file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp,.pdf,.jpg,.jpeg,.png,.webp" required></label><p id="file-info" class="subtle">Belum ada file dipilih.</p><div class="pdf-view" id="upload-preview" hidden></div></div><div class="full"><label for="supporting-files">Bukti pendukung (PDF)</label><input id="supporting-files" name="evidence_files[]" type="file" accept="application/pdf,.pdf" multiple></div></div><div class="callout ${mode==='demo'?'warn':''}">${mode==='demo'?'Ekstraksi hanya untuk fixture terdaftar. PDF lain harus diisi manual dan tidak diberi hasil AI palsu.':'Dokumen akan diproses setelah kamu menekan Buat request. Pastikan invoice dan bukti pendukung sudah sesuai.'}</div><button class="primary" type="submit">Buat request & proses</button></form></div></section><div>${fixtureHTML()}<section class="panel"><div class="panel-body"><h3>Setelah unggah</h3><p class="subtle">Pantau status, lengkapi bukti jika diminta, lalu unduh voucher setelah Finance Reviewer menyetujui.</p></div></section></div></div>`,'upload');let selected=null;const input=document.querySelector('#invoice-file');async function inspect(file){try{selected=await inspectInvoice(file,{allowImages:mode==='live'});document.querySelector('#file-info').textContent=`${file.name} · ${selected.pages} halaman${selected.kind==='image'?' · Foto akan disiapkan menjadi PDF':''} · ${(file.size/1024).toFixed(1)} KB`;const target=document.querySelector('#upload-preview');target.hidden=false;if(selected.kind==='pdf')await previewPDF(selected.bytes,target);else{const picture=document.createElement('img');picture.className='source-image';picture.alt='Pratinjau foto invoice';const url=URL.createObjectURL(file);objectURLs.push(url);picture.src=url;target.replaceChildren(picture);}}catch(e){selected=null;input.value='';toast(e.message,true);}}input.onchange=e=>e.target.files[0]&&inspect(e.target.files[0]);const drop=document.querySelector('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const file=e.dataTransfer.files[0];if(file){const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files;inspect(file);}};document.querySelector('#upload-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);run(async()=>{if(!selected)throw Error('Pilih dan tunggu pemeriksaan dokumen selesai.');for(const file of form.getAll('evidence_files[]'))if(file.size)await inspectPDF(file);const created=await api.upload(form);toast('Request dibuat.');navigate('review',created.id);},false);};}
